import {scoreRun,insertDemoRun,SCORING_RULES} from './scoring.js?v=20';
import {sanitizeCaptainName} from './captain-name.js';
const number=new Intl.NumberFormat('en-US');
const escape=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const formatTime=seconds=>`${Math.floor(seconds/60)}:${String(Math.floor(seconds%60)).padStart(2,'0')}`;
export function scoreMarkup(run,{sample=false}={}){
  const result=scoreRun(run),board=insertDemoRun(result),rows=Array.isArray(board)?board:board.rows;
  for(const row of rows)if(row.isPlayer)row.name=sanitizeCaptainName(run.playerName);
  const medalIcon=position=>['','🏆','🥈','🥉'][position]||'';
  const medal=position=>['','gold','silver','bronze'][position]||'';
  return `<div class="score-hero"><div><span class="section-kicker">${sample?'SAMPLE VOYAGE':'YOUR VOYAGE'} · PROVISIONAL SCORE</span><div class="score-total">${number.format(result.total)}<span>PTS</span></div><p>Every point accounted for. Nothing submitted.</p></div><div class="score-stamp"><span>CAPTAIN'S LOG</span><strong>${escape(result.grade)}</strong><small>${result.status==='won'?'MISSION COMPLETE':'KEEP PRACTICING'}</small></div></div>
  <div class="debrief-grid"><section class="score-breakdown" aria-labelledby="breakdown-title"><div class="section-heading"><h3 id="breakdown-title">The scorecard</h3><span>Draft rules</span></div><div class="score-totals"><div><span>Earned</span><strong class="positive">+${number.format(result.earned)}</strong></div><div><span>Deducted</span><strong class="negative">−${number.format(result.deducted)}</strong></div></div><ul class="score-ledger">${result.rows.map(row=>`<li><div><strong>${escape(row.label)}</strong><small>${escape(row.detail)}</small></div><span class="${row.points>0?'positive':row.points<0?'negative':'neutral'}">${row.points>0?'+':row.points<0?'−':''}${number.format(Math.abs(row.points))}</span></li>`).join('')}</ul><details class="score-rules"><summary>How this mock score works</summary><p>1 point per route metre (up to 1,800), +2,000 for docking, +300 per remaining hull point (up to ${SCORING_RULES.maxHealth}), +${SCORING_RULES.pointsPerSupply} per physically collected supply crate (up to ${SCORING_RULES.maxSupplies}), and −400 per hit. Dock within 3:00 for 10 points per whole second saved. Final score cannot fall below zero.</p><p>These are proposed rules, not a final competitive system. Life crates can also restore a hull point, worth +300 in the hull tally, but they never erase damage penalties. Dispatch, delivery, ignored crates, drone shots, repeated missile spawns and shield interceptions award no direct points.</p></details></section>
  <section class="demo-board" aria-labelledby="leaderboard-title"><div class="section-heading"><h3 id="leaderboard-title">The captain's club</h3><span class="demo-badge">DEMO</span></div><p class="board-disclaimer">Demo league: fictional rivals and sample scores. This is not a live ranking.</p><div class="leaderboard" role="table" aria-label="Demo leaderboard with fictional sample players"><div class="leader-row leaderboard-head" role="row"><span role="columnheader">#</span><span role="columnheader">Captain / voyage</span><span role="columnheader">Points</span></div><div class="leaderboard-body" role="rowgroup">${rows.map((row,index)=>`<div class="leader-row ${row.isPlayer?'you':''} ${medal(index+1)?`medal-${medal(index+1)}`:''}" data-final-position="${index+1}" role="row"><span class="board-position" role="cell">${String(row.demoPosition??index+1).padStart(2,'0')}</span><div role="cell"><strong><span class="medal-icon" aria-hidden="true"${index<3?'':' hidden'}>${medalIcon(index+1)}</span>${escape(row.name)}${row.isPlayer?'<em>YOU</em>':''}<span class="medal-marker" aria-hidden="true">${medal(index+1).toUpperCase()}</span></strong><small>${row.isPlayer?(sample?'Sample voyage':'This device · this run'):'Fictional sample'} · ${formatTime(row.time)} · ${row.health}/${SCORING_RULES.maxHealth} hull</small></div><span class="board-score" role="cell">${number.format(row.score??row.total)}</span></div>`).join('')}</div></div><div class="rank-entry-controls"><span class="rank-announcement" aria-live="polite">Demo position ${rows.find(row=>row.isPlayer)?.demoPosition} of ${rows.length}. Fictional leaderboard.</span><button class="rank-skip hidden" type="button">Skip animation</button><button class="rank-replay" type="button">Replay climb ↟</button></div><div class="board-footnote"><span class="status-dot"></span>No account. No upload. No live rankings.</div></section></div>`;
}
export function renderScoreReport(container,run,options){container.innerHTML=scoreMarkup(run,options);}
